const discord = require("discord.js");
const TTS = require("../../../util/tts");

class Command {
    constructor() {
        this.name = "ttsextra";
        this.description = "extra text too specahj settings";
        this.attributes = {
            permission: 0,
            lockedToCommands: false,
            unlisted: false,
        };

        this.alias = ["etts", "ttse", "extratts",             "speak", "espeak", "speake", "extraspeak", "speakextra"];
    }

    async invoke(message, args, util) {
        const language = args.shift();
        const friendlyVoice = args.shift().toLowerCase();

        // convert friendly voice into model & name options
        let model = "google";
        let name = null;
        switch (friendlyVoice) {
            case "google":
            case "espeak-ng":
                model = friendlyVoice;
                break;
            case "espeak":
                model = "espeak-ng";
                break;
            case "david":
                model = "balabolka";
                name = "Microsoft David Desktop";
                break;
            case "zira":
                model = "balabolka";
                name = "Microsoft Zira Desktop";
                break;
            case "bonzi":
            case "bonzibuddy":
                model = "balabolka";
                name = "x-BonziBUDDY";
                break;
            case "adultmale1":
            case "adultmale2":
            case "adultmale3":
            case "adultmale4":
            case "adultmale5":
            case "adultmale6":
            case "adultmale7":
            case "adultmale8":
                model = "balabolka";
                name = "Adult Male #" + friendlyVoice.split("").pop();
                break;
            case "adultfemale1":
            case "adultfemale2":
                model = "balabolka";
                name = "Adult Female #" + friendlyVoice.split("").pop();
                break;
            default:
                return message.reply("bro thought");
        }

        const speakText = args.join(" ");
        const buffer = await TTS.speak(speakText, model, language, name);
        const attachment = new discord.MessageAttachment(buffer, "speech.mp3");

        message.reply({
            content: `Generated by <@${message.author.id}>`,
            files: [attachment]
        });
    }
}

// needs to do new Command() in index.js because typing static every time STINKS!
module.exports = Command;